$('collab-toggle').addEventListener('click',async()=>{if(!active)return;const wasCollab=inspectorMode==='collab'||inspectorMode==='agent';if(wasCollab)$('evidence').hidden=!$('evidence').hidden;else $('evidence').hidden=false;inspectorMode='collab';collabAgentId=null;syncInspector();if($('evidence').hidden)return;try{await renderCollab();}catch(error){notice(error.message);}if(window.matchMedia('(max-width:760px)').matches){$('evidence').tabIndex=-1;$('evidence').focus();$('evidence').scrollIntoView({block:'start'});}});
const recoveryKindLabels={resume:'待恢复',verify_write:'待核实写入',queued:'排队续接',command_failed:'操作失败'};
const recoveryNote='浏览器关闭不会中断执行；重新打开页面会用持久事件序号补齐。服务进程退出或机器重启会中断执行中的任务。普通中断需要显式恢复；未知写入需要宿主核实实际副作用后再决定。';
function shortDigest(value){return typeof value==='string'&&value.length>8?value.slice(0,8):(value||'未知');}
function closeStream(){if(stream){stream.close();stream=null;}}
function setConnection(state,text){connectionState=state;const bar=$('connection-bar');if(bar){bar.setAttribute('data-state',state);bar.title=serverStartedAt?text+' · 服务启动于 '+new Date(serverStartedAt).toLocaleString():text;}const label=$('connection-text');if(label)label.textContent=text;const retry=$('connection-retry');if(retry)retry.hidden=state!=='offline'&&state!=='reauth';}
function scheduleConnectedReset(){clearTimeout(reconnectedTimer);reconnectedTimer=setTimeout(function(){if(connectionState==='reconnected')setConnection('connected','已连接');},5000);}
function showReconnected(count){clearTimeout(reconnectedTimer);setConnection('reconnected',count>0?'已重新连接，补齐 '+count+' 条遗漏事件':'已重新连接，事件已同步');scheduleConnectedReset();}
function connectionFailed(){if(!everConnected||connectionState==='reauth')return;setConnection('offline','无法连接本地服务，请确认终端中的 kodo serve 仍在运行');}
async function probeConnection(force){const now=Date.now();if(probeInFlight||(!force&&now-lastProbeAt<2000))return;probeInFlight=true;lastProbeAt=now;try{const response=await fetch('/api/state',{cache:'no-store'});if(response.status===401){enterReauth();return;}if(response.ok){if(streamDisconnected)setConnection('reconnecting','连接中断，正在重新连接…');else if(connectionState==='offline')setConnection('connected','已连接');return;}setConnection('offline','无法连接本地服务，请确认终端中的 kodo serve 仍在运行');}catch(error){if(everConnected)setConnection('offline','无法连接本地服务，请确认终端中的 kodo serve 仍在运行');}finally{probeInFlight=false;}}
function onStreamError(){if(!stream)return;if(!streamDisconnected){streamDisconnected=true;disconnectCursor=cursor;reconnectCount=0;reconnectSeen=new Set();}$('status').textContent='连接中断，正在恢复事件…';setConnection('reconnecting','连接中断，正在重新连接…');clearTimeout(reconnectSettleTimer);void probeConnection(false);}
function scheduleReconnectSettle(){if(!streamDisconnected)return;clearTimeout(reconnectSettleTimer);reconnectSettleTimer=setTimeout(function(){void settleReconnect();},350);}
async function settleReconnect(){if(!streamDisconnected)return;streamDisconnected=false;clearTimeout(reconnectSettleTimer);const count=reconnectCount;try{await refresh();}catch(error){if(error.status!==401)notice(error.message);}await loadRecovery();showReconnected(count);if(packagesOpen)await loadPackages();}
function enterReauth(){if(connectionState==='reauth'){$('connect').hidden=false;return;}if(!everConnected&&connectionState!=='reconnecting'&&connectionState!=='offline')return;lastActive=active;closeStream();connected=false;streamDisconnected=false;clearTimeout(reconnectSettleTimer);clearTimeout(reconnectedTimer);clearTimeout(refreshTimer);setConnection('reauth','服务已重启或会话失效，请用新的启动密钥重新连接');$('connect').hidden=false;$('message').disabled=true;$('send').disabled=true;notice('服务已重启或会话失效，请用新的启动密钥重新连接。上次任务已保留，重新认证后会尝试恢复。');try{$('connect').scrollIntoView({block:'nearest'});$('secret').focus();}catch(error){/* 无法聚焦时保持表单可见即可。 */}}
async function restoreActive(items){if(!active)return;if(!items.some(function(run){return run.id===active;})){active=null;lastActive=null;snapshot=null;closeStream();resetCollab();$('title').textContent='把目标交给 Kodo';$('status').textContent='创建新任务';$('chat').replaceChildren(element('div','上次任务在当前服务中不可访问，请从任务记录中选择或新建任务。','welcome'));$('questions').hidden=true;$('cancel').hidden=true;$('resume').hidden=true;notice('上次任务在当前服务中不可访问，已清空选择。');return;}try{await select(active);}catch(error){notice(error.message);}}
function updateRecoveryBadge(){const badge=$('recovery-badge');if(!badge)return;const count=recovery&&Array.isArray(recovery.items)?recovery.items.length:0;badge.textContent=count>0?String(count):'';badge.hidden=count===0;const button=$('recovery-toggle');if(!button)return;button.disabled=!connected;button.title=count>0?'恢复与核实：'+count+' 项需要处理':'恢复与核实';button.setAttribute('aria-label','恢复与核实，'+count+' 项需要处理');}
async function loadRecovery(){if(!connected)return;try{const data=await api('/api/recovery');recovery=data&&Array.isArray(data.items)?data:null;recoveryError=null;}catch(error){if(error.status===401)return;if(error.status===404){recovery=null;recoveryError='当前服务未提供恢复视图，请使用支持恢复视图的新版本启动服务。';}else recoveryError=error.message;}updateRecoveryBadge();if(inspectorMode==='recovery'&&!$('evidence').hidden)await renderRecovery();}
function renderRecoveryItem(item){const severity=item.kind==='verify_write'?'critical':item.kind==='command_failed'?'warning':'info';const card=element('section',undefined,'recovery-item '+severity);const head=element('div',undefined,'pending-head');head.append(element('span',recoveryKindLabels[item.kind]||item.kind,'tag'),element('span',item.role==='main'?'主任务':'子任务','tag'),element('span',labels[item.status]||item.status,'tag'));card.append(head,element('p',item.objective||'','pending-title'));card.append(collabMetaLine('状态',(labels[item.status]||item.status)+(item.error?' · '+item.error:'')));if(item.lastEventAt)card.append(collabMetaLine('最后事件',new Date(item.lastEventAt).toLocaleString()));if(item.kind==='verify_write')card.append(element('p','未知写入不会自动恢复；请先核实实际副作用，再由宿主决定是否恢复。','pending-detail'));else if(item.kind==='resume')card.append(element('p','中断只是执行停止；恢复会在批准的权限内继续，恢复前请核对上下文与产物。','pending-detail'));else if(item.kind==='queued')card.append(element('p','任务已接受并在排队；浏览器关闭不影响服务端继续推进。','pending-detail'));else if(item.kind==='command_failed')card.append(element('p','Web 命令异步失败；请查看任务证据后重试或取消。','pending-detail'));const actions=element('div',undefined,'recovery-actions');if(item.kind==='resume'&&item.role==='main')actions.append(actionButton('恢复执行',async function(){await mutate('/api/runs/'+encodeURIComponent(item.runId)+'/resume',{});notice('已提交恢复请求；未知写入仍需宿主核实。');await loadRecovery();if(active===item.runId)await refresh();}));actions.append(actionButton('查看任务',function(){return viewRecoveryTask(item);}));if(item.kind==='verify_write')actions.append(actionButton('查看证据',function(){return inspectRecoveryEvidence(item);}));card.append(actions);return card;}
async function renderRecovery(){const panel=$('recovery-content');if(!panel||inspectorMode!=='recovery')return;setInspectorHeading('恢复与核实','中断、未知写入、排队与 Web 命令失败；未知写入需要宿主核实。');syncInspector();panel.replaceChildren();panel.append(element('p',recoveryNote,'muted'));if(recoveryError)panel.append(element('p','恢复视图读取失败：'+recoveryError,'muted'));if(!recovery){panel.append(element('p','正在读取恢复视图…','muted'),actionButton('重新读取',function(){return loadRecovery();}));return;}const counts=recovery.counts||{};panel.append(element('p','共 '+recovery.items.length+' 项 · 待恢复 '+(counts.resume||0)+' · 待核实写入 '+(counts.verify_write||0)+' · 排队续接 '+(counts.queued||0)+' · 操作失败 '+(counts.command_failed||0)+' · 生成于 '+new Date(recovery.generatedAt||Date.now()).toLocaleTimeString(),'collab-note'));if(!recovery.items.length){panel.append(element('p','没有需要恢复或核实的任务。','muted'));return;}panel.append(element('h3','需要恢复或核实（'+recovery.items.length+'）'));for(const item of recovery.items)panel.append(renderRecoveryItem(item));}
async function viewRecoveryTask(item){if(item.role==='child'&&item.parentId){await select(item.parentId);$('evidence').hidden=false;inspectorMode='collab';collabAgentId=null;syncInspector();await renderCollab();return;}await select(item.runId);}
async function inspectRecoveryEvidence(item){await select(item.runId);$('evidence').hidden=false;inspectorMode='evidence';syncInspector();setInspectorHeading('执行证据','查看调用、事件与产物，核对实际结果。');if(snapshot)await evidence(snapshot);}
$('recovery-toggle').addEventListener('click',async()=>{const same=inspectorMode==='recovery';inspectorMode='recovery';collabAgentId=null;$('evidence').hidden=same?!$('evidence').hidden:false;syncInspector();updateRecoveryBadge();if($('evidence').hidden)return;try{await loadRecovery();}catch(error){notice(error.message);}if(window.matchMedia('(max-width:760px)').matches){$('evidence').tabIndex=-1;$('evidence').focus();$('evidence').scrollIntoView({block:'start'});}});
$('connection-retry').addEventListener('click',()=>{if(connectionState==='reauth'){$('connect').hidden=false;try{$('secret').focus();}catch(error){/* 保持表单可见即可。 */}return;}void probeConnection(true);});
const packageStatusLabels={imported:'已导入',needs_configuration:'需要配置',incompatible:'不兼容',ready:'就绪'};
const prepareStatusLabels={queued:'排队中',running:'运行中',succeeded:'已完成',failed:'失败'};
const preparePhaseLabels={queued:'排队中',validating:'校验中',dependencies:'安装依赖',verifying:'验证中',committing:'提交中',done:'已完成',failed:'失败'};
function updatePackagesButton(){const button=$('packages-toggle');if(!button)return;const enabled=!!(packagesOverview&&packagesOverview.enabled);button.disabled=!connected||!enabled;button.title=enabled?'能力包开发：兼容性诊断、依赖准备与默认版本':'能力包面板未启用；请使用 kodo serve --packages 启动本地服务';button.setAttribute('aria-label',enabled?'能力包开发':'能力包面板未启用');if(!enabled&&packagesOpen)closePackages();}
async function loadPackages(){if(!connected)return;try{const data=await api('/api/packages');packagesOverview=data;packagesError=null;if(data&&Array.isArray(data.prepareJobs))for(const job of data.prepareJobs)if(job&&typeof job.id==='string')prepareJobs.set(job.id,job);}catch(error){if(error.status===401)return;if(error.status===404){packagesOverview=null;packagesError='当前服务未提供能力包视图，请使用支持能力包面板的新版本启动服务。';}else packagesError=error.message;}updatePackagesButton();if(packagesOpen){renderPackages();if(hasPendingPrepare())schedulePreparePoll();}}
function latestPrepareJob(packageId,version){let found=null;for(const job of prepareJobs.values()){if(job.packageId!==packageId||job.version!==version)continue;if(!found){found=job;continue;}const active=job.status==='queued'||job.status==='running';const foundActive=found.status==='queued'||found.status==='running';if(active!==foundActive){if(active)found=job;}else{const a=job.finishedAt||job.startedAt||'';const b=found.finishedAt||found.startedAt||'';if(a>b)found=job;}}return found;}
function prepareElapsed(job){const start=job.startedAt?Date.parse(job.startedAt):prepareStartedAt.get(job.id);const end=job.finishedAt?Date.parse(job.finishedAt):Date.now();if(!start||Number.isNaN(start))return 0;return Math.max(0,Math.round((end-start)/1000));}
function renderPrepareStatus(job,packageId,version){const box=element('section',undefined,'prepare-status');box.append(element('p','依赖准备：'+(prepareStatusLabels[job.status]||job.status)+' · 阶段 '+(preparePhaseLabels[job.phase]||job.phase)+' · 已用 '+prepareElapsed(job)+' 秒'));if(job.status==='queued')box.append(element('p','同一时刻只运行一个依赖准备任务，稍后自动开始。','package-note'));if(job.status==='failed'){box.append(element('p','失败原因：'+(job.error||'未知，请查看宿主日志'),'package-note'));box.append(actionButton('重试准备依赖',async function(){await startPrepare(packageId,version);}));}if(job.status==='succeeded')box.append(element('p','依赖准备完成，已重新诊断；准备结果会显示在版本卡片中。','package-note'));return box;}
async function startPrepare(packageId,version){const result=await mutate('/api/packages/'+encodeURIComponent(packageId)+'/'+encodeURIComponent(version)+'/prepare',{});const jobId=result&&result.jobId;if(typeof jobId!=='string')throw new Error('依赖准备没有返回任务编号，请重试。');prepareStartedAt.set(jobId,Date.now());prepareJobs.set(jobId,{id:jobId,packageId,version,status:'queued',phase:'queued',startedAt:null,finishedAt:null,error:null});notice('已排队准备依赖；进度会显示在能力包面板中。');if(packagesOpen){renderPackages();schedulePreparePoll();}await refreshPrepareJob(jobId);}
async function refreshPrepareJob(jobId){try{const data=await api('/api/packages/jobs/'+encodeURIComponent(jobId));if(data&&typeof data.id==='string')prepareJobs.set(jobId,data);}catch(error){if(error.status===404){prepareJobs.delete(jobId);}else if(error.status)notice(error.message);return;}if(packagesOpen)renderPackages();const job=prepareJobs.get(jobId);if(job&&(job.status==='succeeded'||job.status==='failed'))await loadPackages();}
function hasPendingPrepare(){for(const job of prepareJobs.values())if(job.status==='queued'||job.status==='running')return true;return false;}
function stopPackagesTimer(){clearTimeout(packagesTimer);packagesTimer=null;}
function schedulePreparePoll(){stopPackagesTimer();if(!packagesOpen||!hasPendingPrepare())return;packagesTimer=setTimeout(async function(){packagesTimer=null;if(!packagesOpen)return;let unreachable=false;for(const jobId of Array.from(prepareJobs.keys())){const job=prepareJobs.get(jobId);if(!job||(job.status!=='queued'&&job.status!=='running'))continue;try{const data=await api('/api/packages/jobs/'+encodeURIComponent(jobId));if(data&&typeof data.id==='string')prepareJobs.set(jobId,data);}catch(error){if(error.status===404)prepareJobs.delete(jobId);else if(error.status)notice(error.message);else{unreachable=true;break;}}}if(unreachable){connectionFailed();return;}if(hasPendingPrepare()){if(packagesOpen)renderPackages();schedulePreparePoll();}else if(packagesOpen)await loadPackages();},1000);}
function renderPackages(){const panel=$('packages-content');if(!panel||!packagesOpen)return;const state=captureCollabDrafts(panel);panel.replaceChildren();if(!packagesOverview){panel.append(element('p','正在读取能力包诊断…','muted'));if(packagesError)panel.append(element('p','能力包视图读取失败：'+packagesError,'muted'),actionButton('重新读取',function(){return loadPackages();}));restoreCollabDrafts(panel,state);return;}if(!packagesOverview.enabled){panel.append(element('p','宿主未开启能力包面板。请使用 kodo serve --packages 启动只读面板；需要依赖准备或切换默认版本时，再加 --package-actions。','muted'));restoreCollabDrafts(panel,state);return;}const actions=packagesOverview.actions||{};const runtime=packagesOverview.runtime;const runtimeBox=element('section',undefined,'packages-runtime');runtimeBox.append(element('h3','当前 Web 服务启用'));if(runtime)runtimeBox.append(element('p','当前 Web 服务启用：'+runtime.id+'@'+runtime.version+'（摘要 '+shortDigest(runtime.digest)+'）。新任务使用此卡片；切换默认版本不会改变已运行任务。'));else runtimeBox.append(element('p','当前 Web 服务未启用能力包；新任务使用宿主默认卡片。'));panel.append(runtimeBox);const errors=(packagesOverview.errors||[]).slice();if(packagesError&&errors.indexOf(packagesError)<0)errors.unshift(packagesError);if(errors.length){const errorBox=element('section',undefined,'package-error');errorBox.append(element('p','能力包读取或诊断错误：'));for(const message of errors)errorBox.append(element('p',message));panel.append(errorBox);}const packages=packagesOverview.packages||[];panel.append(element('h3','已安装能力包（'+packages.length+'）'));if(!packages.length)panel.append(element('p','宿主没有登记已安装的能力包。','muted'));for(const group of packages)panel.append(renderPackageGroup(group,actions));panel.append(renderRunningPackages(packagesOverview.running||[]));restoreCollabDrafts(panel,state);}
function renderPackageGroup(group,actions){const section=element('section',undefined,'package-group');const head=element('div',undefined,'package-group-head');head.append(element('h3',group.id),element('span','默认版本 '+(group.defaultVersion||'未设置')+' · 上一版本 '+(group.previousVersion||'无'),'package-group-note'));section.append(head);if(group.adoptedAt)section.append(element('p','采用时间 '+new Date(group.adoptedAt).toLocaleString()+' · 默认版本指针只影响后续新任务。','package-group-note'));const versions=group.versions||[];if(!versions.length)section.append(element('p','没有登记的版本。','muted'));for(const version of versions)section.append(renderPackageVersion(group,version,actions));if(actions.adopt&&group.previousVersion){const box=element('div',undefined,'package-actions');box.append(actionButton('回退默认版本',async function(){await mutate('/api/packages/'+encodeURIComponent(group.id)+'/rollback',{});notice('已回退默认版本到 '+group.previousVersion+'；已运行任务不受影响。');await loadPackages();}),element('span','回退只切换默认版本指针；已运行任务的卡片不会改变。','package-note'));section.append(box);}return section;}
function renderPackageVersion(group,version,actions){const isDefault=group.defaultVersion===version.version;const card=element('section',undefined,'package-version'+(isDefault?' default':''));const head=element('div',undefined,'package-version-head');head.append(element('span',group.id+'@'+version.version,'tag'),element('span',packageStatusLabels[version.status]||version.status,'tag pkg-'+(version.status||'imported')),element('span','摘要 '+shortDigest(version.digest),'tag'));if(isDefault)head.append(element('span','当前默认版本','tag pkg-ready'));card.append(head);const info=version.card||{};card.append(element('h4',(info.name||info.id||'未命名卡片')+(info.version?' · 卡片版本 '+info.version:'')));if(info.description)card.append(element('p',info.description));if(info.digest)card.append(element('p','卡片摘要 '+shortDigest(info.digest),'package-meta'));const reasons=version.reasons||[];if(reasons.length){card.append(element('p','诊断原因：','package-meta'));const list=element('ul',undefined,'package-reasons');for(const reason of reasons)list.append(element('li',reason));card.append(list);}const resources=version.resources||{tools:0,skills:0,mcp:0};card.append(element('p','资源：工具 '+(resources.tools||0)+' · Skill '+(resources.skills||0)+' · MCP '+(resources.mcp||0)+' · 例子 '+(version.examples||0),'package-meta'));const requirements=version.requirements||{};const requirementBits=[];if(requirements.node)requirementBits.push('Node '+requirements.node);if(requirements.platforms&&requirements.platforms.length)requirementBits.push('平台 '+requirements.platforms.join('/'));if(requirements.arch&&requirements.arch.length)requirementBits.push('架构 '+requirements.arch.join('/'));const dependencies=requirements.dependencies||{};const dependencyNames=Object.keys(dependencies);if(dependencyNames.length)requirementBits.push('依赖声明 '+dependencyNames.map(function(name){return name+'@'+(dependencies[name]||'*');}).join('、'));card.append(element('p','requirements：'+(requirementBits.length?requirementBits.join(' · '):'无特殊要求'),'package-meta'));const prepared=version.prepared||{ready:false,treeDigest:null};card.append(element('p','依赖准备：'+(prepared.ready?'已准备'+(prepared.treeDigest?'（treeDigest '+shortDigest(prepared.treeDigest)+'）':''):'未准备'),'package-meta'));card.append(element('p','宿主绑定：'+(version.bindingsConfigured?'已配置（不显示绑定内容）':'未配置'),'package-meta'));const provenance=version.provenance;if(provenance){const source=provenance.source||{};const provenanceBits=[];if(source.url)provenanceBits.push('来源 '+source.url+(source.revision?'@'+source.revision:''));if(provenance.importedAt)provenanceBits.push('导入 '+new Date(provenance.importedAt).toLocaleString());if(provenance.archiveName)provenanceBits.push('归档 '+provenance.archiveName);card.append(element('p','provenance：'+(provenanceBits.length?provenanceBits.join(' · '):'无'),'package-meta'));}else card.append(element('p','provenance：没有来源记录','package-meta'));const job=latestPrepareJob(group.id,version.version);const jobActive=!!job&&(job.status==='queued'||job.status==='running');const actionBox=element('div',undefined,'package-actions');if(actions.prepare){if(dependencyNames.length&&!prepared.ready&&!jobActive)actionBox.append(actionButton('准备依赖',async function(){await startPrepare(group.id,version.version);}));}else if(dependencyNames.length&&!prepared.ready)actionBox.append(element('span','宿主未开启依赖准备（--package-actions）。','package-note'));if(actions.adopt&&!isDefault)actionBox.append(actionButton('设为默认版本',async function(){await mutate('/api/packages/'+encodeURIComponent(group.id)+'/adopt',{version:version.version});notice('已把 '+group.id+'@'+version.version+' 设为默认版本；已运行任务不受影响。');await loadPackages();}));if(!actions.adopt)actionBox.append(element('span','宿主未开启默认版本切换（--package-actions）。','package-note'));if(actionBox.childNodes.length)card.append(actionBox);if(job&&(jobActive||job.status==='failed'||(job.status==='succeeded'&&!prepared.ready)))card.append(renderPrepareStatus(job,group.id,version.version));return card;}
function renderRunningPackages(running){const section=element('section');section.append(element('h3','运行版本（'+running.length+'）'),element('p','任务卡片在创建时固定；升级能力包或切换默认版本不会改变已运行任务，恢复旧任务仍需重新启用相同包摘要。','muted'));if(!running.length)section.append(element('p','当前没有使用能力包的可见任务。','muted'));for(const item of running){const card=element('section',undefined,'package-run');const head=element('div',undefined,'package-version-head');head.append(element('span',item.role==='main'?'主任务':'子任务','tag'),element('span',labels[item.status]||item.status,'tag'));if(item.stale)head.append(element('span','stale · 已安装摘要与卡片摘要不一致','agent-flag warn'));card.append(head,element('p',item.objective||'','pending-title'),element('p','卡片版本：'+item.cardId+'@'+item.cardVersion+' · 卡片摘要 '+shortDigest(item.cardDigest)+' · 已安装摘要 '+(item.installedDigest?shortDigest(item.installedDigest):'未知'),'package-meta'),element('p','任务卡片在创建时固定，不会随默认版本切换而改变。','package-meta'));section.append(card);}return section;}
function openPackages(){if(!(packagesOverview&&packagesOverview.enabled))return;closeKnowledge();packagesOpen=true;$('packages-panel').hidden=false;$('task-workspace').hidden=true;$('packages-toggle').setAttribute('aria-expanded','true');renderPackages();if(hasPendingPrepare())schedulePreparePoll();}
function closePackages(){packagesOpen=false;stopPackagesTimer();const panel=$('packages-panel');if(panel)panel.hidden=true;const workspace=$('task-workspace');if(workspace)workspace.hidden=false;const button=$('packages-toggle');if(button)button.setAttribute('aria-expanded','false');}
$('packages-toggle').addEventListener('click',async()=>{if(!(packagesOverview&&packagesOverview.enabled)){notice('能力包面板未启用；请使用 kodo serve --packages 启动本地服务（需要依赖准备或切换默认版本时再加 --package-actions）。');return;}if(packagesOpen){closePackages();return;}openPackages();await loadPackages();});
$('packages-refresh').addEventListener('click',async()=>{try{await loadPackages();}catch(error){notice(error.message);}});
$('packages-close').addEventListener('click',closePackages);
updateCollabBadge();updateRecoveryBadge();updatePackagesButton();syncInspector();
ready().catch(error=>{if(error.status!==401)notice(error.message);});
